const r="http://localhost:8000";async function t(e){try{const a=await fetch(`${r}/cameras/test-rtsp`,{method:"POST",headers:{"Content-Type":"application/json"},credentials:"include",body:JSON.stringify({rtspUrl:e})});return a.ok?await a.json():{success:!1,latencyMs:null,errorMessage:"Server error",resolution:null}}catch(a){return{success:!1,latencyMs:null,errorMessage:a instanceof Error?a.message:"Connection failed",resolution:null}}}async function s(e){const a=await fetch(`${r}/cameras/manual`,{method:"POST",headers:{"Content-Type":"application/json"},credentials:"include",body:JSON.stringify({...e,addMethod:"manual"})});if(!a.ok)throw new Error("Failed to add camera");return await a.json()}async function n(){const e=await fetch(`${r}/cameras/discover`,{method:"POST",credentials:"include"});if(!e.ok)throw new Error("Network discovery failed");return await e.json()}async function o(e){const a=await fetch(`${r}/cameras/auto-save`,{method:"POST",headers:{"Content-Type":"application/json"},credentials:"include",body:JSON.stringify({cameras:e})});if(!a.ok)throw new Error("Failed to save discovered cameras");return await a.json()}async function c(){const e=await fetch(`${r}/cameras`,{credentials:"include"});if(!e.ok)throw new Error("Failed to load cameras");return await e.json()}async function i(e){if(!(await fetch(`${r}/cameras/${e}`,{method:"DELETE",credentials:"include"})).ok)throw new Error("Failed to delete camera")}export{s as a,i as b,n as d,c as f,o as s,t};
